shader.code:
// Deep Field: a volumetric flight through a fractal cosmos. Each ray samples
// a folded, inverted space (p = |p| / p.p - form) in shells of growing
// distance; the folding leaves dust, filaments and star clusters at every
// scale. Form reshapes the whole universe, Swirl bends the light around the
// centre of the view like a gravitational lens. Based on the volumetric
// technique of Kali's "Star Nest".

#define TAU 6.28318531

mat2 rot(float a) {
  float c = cos(a);
  float s = sin(a);
  return mat2(c, -s, s, c);
}

vec3 palette(float t) {
  return 0.5 + 0.5 * cos(TAU * (t + vec3(0.0, 0.33, 0.67)));
}

vec3 shader(vec2 uv, float time) {
  float j = drift + kick;
  vec2 p = (uv - 0.5) * vec2(resolution.x / resolution.y, 1.0);

  // Gravitational lens: light near the centre is dragged around it.
  float rad = length(p);
  p = rot(swirl * 2.5 * exp(-rad * 2.5) * sin(j * 0.06 + 1.0)) * p;
  p *= 1.0 - swirl * 0.5 * exp(-rad * rad * 6.0);

  vec3 dir = normalize(vec3(p * mix(2.2, 0.5, zoom), 1.0));
  dir.xz = rot(0.5 + j * 0.009) * dir.xz;
  dir.xy = rot(0.8 + j * 0.013) * dir.xy;
  vec3 from = vec3(1.0, 0.5, 0.5) + vec3(0.02, 0.011, -0.013) * j;

  // The universe's constant drifts slightly along the journey.
  float fp = mix(0.56, 0.68, form) + 0.012 * sin(j * 0.031);
  float hue = colour + j * 0.007;

  float s = 0.1;
  float fade = 1.0;
  vec3 acc = vec3(0.0);
  for (int k = 0; k < 16; k++) {
    vec3 q = from + s * dir * 0.5;
    // Mirror-tile space so the flight never leaves the structure.
    q = abs(vec3(0.85) - mod(q, vec3(1.7)));
    float pa = 0.0;
    float a = 0.0;
    for (int i = 0; i < 15; i++) {
      q = abs(q) / max(dot(q, q), 1e-6) - fp;
      float l = length(q);
      a += abs(l - pa);
      pa = l;
    }
    // Dark matter: voids swallow the light of the shells behind them.
    float dm = max(0.0, 0.3 - a * a * 0.001);
    a *= a * a;
    if (k > 5) fade *= 1.0 - dm;
    // Each shell has its own colour, so depth reads as a spectrum.
    vec3 tint = palette(hue + s * 0.55);
    acc += fade * 0.6 * mix(vec3(1.0), tint, 0.7);
    acc += tint * s * a * 0.0017 * fade;
    fade *= 0.73;
    s += 0.1;
  }
  vec3 col = acc * 0.01 * mix(0.4, 1.6, shine);
  // Compress brightness but keep the hue, so bright clusters glow in
  // colour; only their very cores burn out to white.
  float peak = max(col.r, max(col.g, col.b)) + 1e-4;
  col /= 1.0 + 0.9 * peak;
  col = mix(col, vec3(1.0), 0.6 * smoothstep(4.0, 40.0, peak));
  return clamp(col, 0.0, 1.0);
}
